vector<int> sieve(int limit){
    if(limit < 2) return {};
    vector<char> is(limit+1, 1);
    is[0]=is[1]=0;
    for(int i=2; (long long)i*i<=limit; ++i) if(is[i]){
        for(int j=i*i;j<=limit;j+=i) is[j]=0;
    }
    vector<int> P;
    for(int i=2;i<=limit;i++) if(is[i]) P.push_back(i);
    return P;
}

unordered_map<unsigned long long, long long> dp;
long long recur(long long x, int a, const vector<int>& primes){
    if(a == 0) return x;
    if(x == 0) return 0;
    unsigned long long key = ( (unsigned long long)x << 32 ) | (unsigned long long)(uint32_t)a;
    auto it = dp.find(key);
    if(it != dp.end()) return it->second;
    long long res = recur(x, a-1, primes) - recur(x / primes[a-1], a-1, primes);
    dp[key] = res;
    return res;
}
bool isprime(long long k) {
    for(long long i = 2; i * i <= k; i++) {
        if(k % i == 0) {
            return false;
        }
    }
    return true;
}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    if(!(cin >> n >> k)) return 0;

    long long m = k + 1;
    if(m > n){
        cout << 0 << "\n";
        return 0;
    }
    long long N = n / m;
    if(N == 0){
        cout << 0 << "\n";
        return 0;
    }

    int sieve_limit = (int)min(k, N);
    if(sieve_limit < 2) sieve_limit = 2;
    vector<int> primes = sieve(sieve_limit);

    bool check = false;
    long long mm = m;
    for(int p : primes){
        if((long long)p * (long long)p > mm) break;
        if(mm % p == 0){ check = true; break; }
    }
    check |= !isprime(m);
    if(check){
        cout << 0 << "\n";
        return 0;
    }

    int a = (int)primes.size();
    dp.clear();
    long long ans = recur(N, a, primes);
    cout << ans;
}
